:root {
  --mjx-fg-red: 255, 0, 0;
  --mjx-fg-green: 0, 255, 0;
  --mjx-fg-blue: 0, 0, 255;
  --mjx-fg-yellow: 255, 255, 0;
  --mjx-fg-cyan: 0, 255, 255;
  --mjx-fg-magenta: 255, 0, 255;
  --mjx-fg-white: 255, 255, 255;
  --mjx-fg-black: 0, 0, 0;
  --mjx-bg-red: 255, 0, 0;
  --mjx-bg-green: 0, 255, 0;
  --mjx-bg-blue: 0, 0, 255;
  --mjx-bg-yellow: 255, 255, 0;
  --mjx-bg-cyan: 0, 255, 255;
  --mjx-bg-magenta: 255, 0, 255;
  --mjx-bg-white: 255, 255, 255;
  --mjx-bg-black: 0, 0, 0;
  --mjx-live-bg-color: white;
  --mjx-live-shadow-color: #888;
  --mjx-live-border-color: #CCCCCC;
  --mjx-bg1-color: rgba(var(--mjx-bg-blue), var(--mjx-bg1-alpha));
  --mjx-fg1-color: rgba(var(--mjx-fg-black), 1);
  --mjx-bg2-color: rgba(var(--mjx-bg-red), 1);
  --mjx-fg2-color: rgba(var(--mjx-fg-black), 1);
  --mjx-bg1-alpha: 0.2;
  --mjx-fg1-alpha: 1;
  --mjx-bg2-alpha: 1;
  --mjx-fg2-alpha: 1;
}

@media (prefers-color-scheme: dark) {
  :root {
    --mjx-bg-blue: 132, 132, 255;
      --mjx-bg-white: 0, 0, 0;
      --mjx-bg-black: 255, 255, 255;
      --mjx-fg-white: 0, 0, 0;
      --mjx-fg-black: 255, 255, 255;
      --mjx-live-bg-color: #222025;
      --mjx-live-shadow-color: black;
      --mjx-live-border-color: #7C7C7C;
      --mjx-bg1-alpha: 0.3;
      --mjx-fg1-alpha: 1;
      --mjx-bg2-alpha: 1;
      --mjx-fg2-alpha: 1;
  }
}

.MJX_LiveRegion {
  position: absolute;
  top: 0;
  display: none;
  width: auto;
  height: auto;
  padding: 0;
  opacity: 1;
  z-index: 202;
  left: 0;
  right: 0;
  margin: 0 auto;
  background-color: var(--mjx-live-bg-color);
  box-shadow: 0px 5px 20px var(--mjx-live-shadow-color);
  border: 2px solid var(--mjx-live-border-color);
}

.MJX_LiveRegion_Show {
  display: block;
}

.MJX_LiveRegion > div {
  color: var(--mjx-fg1-color);
  background-color: var(--mjx-bg1-color);
}

mjx-container [data-sre-highlight-1]:not([data-mjx-collapsed], rect) {
  color: var(--mjx-fg1-color) ! important;
  fill: var(--mjx-fg1-color) ! important;
}

mjx-container:not([data-mjx-clone-container]) [data-sre-highlight-1]:not([data-sre-enclosed], rect) {
  background-color: var(--mjx-bg1-color) ! important;
}

mjx-container rect[data-sre-highlight-1]:not([data-sre-enclosed]) {
  fill: var(--mjx-bg1-color) ! important;
}

mjx-container [data-sre-highlight-2] {
  color: var(--mjx-fg2-color) ! important;
  background-color: var(--mjx-bg2-color) ! important;
  fill: var(--mjx-fg2-color) ! important;
}

mjx-container rect[data-sre-highlight-2] {
  fill: var(--mjx-bg2-color) ! important;
}

.MJX_HoverRegion {
  display: block;
  position: absolute;
  width: max-content;
  height: auto;
  padding: 0;
  opacity: 1;
  z-index: 202;
  margin: 0 auto;
  background-color: white;
  line-height: 0;
  box-shadow: 0px 10px 20px #888;
  border: 2px solid #CCCCCC;
}

.MJX_HoverRegion > div {
  overflow: hidden;
  color: var(--mjx-fg1-color);
  background-color: var(--mjx-bg1-color);
}

@media (prefers-color-scheme: dark) {
  .MJX_HoverRegion {
    background-color: #222025;
      box-shadow: 0px 5px 20px #000;
      border: 1px solid #7C7C7C;
  }
}

mjx-container[data-mjx-clone-container] {
  padding: 2px ! important;
}

mjx-math > mjx-mlabeledtr {
  display: inline-block;
  margin-right: .5em ! important;
}

mjx-math > mjx-mtd {
  float: right;
}

mjx-container[overflow="scroll"][display] {
  overflow: auto clip;
  min-width: initial !important;
}

mjx-container[overflow="truncate"][display] {
  overflow: hidden clip;
  min-width: initial !important;
}

mjx-container[display] {
  display: block;
  text-align: center;
  justify-content: center;
  margin: .7em 0;
  padding: .3em 2px;
}

mjx-container[display][width="full"] {
  display: flex;
}

mjx-container[justify="left"] {
  text-align: left;
  justify-content: left;
}

mjx-container[justify="right"] {
  text-align: right;
  justify-content: right;
}

mjx-container[jax="CHTML"] {
  white-space: nowrap;
}

mjx-mo > mjx-c, mjx-mi > mjx-c, mjx-mn > mjx-c, mjx-ms > mjx-c, mjx-mtext > mjx-c {
  clip-path: padding-box polygon(-1em -2px, calc(100% + 1em) -2px, calc(100% + 1em) calc(100% + 2px), -1em calc(100% + 2px));
}

mjx-stretchy-h {
  clip-path: padding-box polygon(0 -2px, 100% -2px, 100% calc(100% + 2px), 0 calc(100% + 2px));
  display: inline-block;
}

mjx-stretchy-v {
  clip-path: padding-box polygon(-2px 0, calc(100% + 2px) 0, calc(100% + 2px) 100%, -2px 100%);
  display: inline-block;
  text-align: center;
}

mjx-container [space="1"] {
  margin-left: .111em;
}

mjx-container [space="2"] {
  margin-left: .167em;
}

mjx-container [space="3"] {
  margin-left: .222em;
}

mjx-container [space="4"] {
  margin-left: .278em;
}

mjx-container [space="5"] {
  margin-left: .333em;
}

mjx-container [rspace="1"] {
  margin-right: .111em;
}

mjx-container [rspace="2"] {
  margin-right: .167em;
}

mjx-container [rspace="3"] {
  margin-right: .222em;
}

mjx-container [rspace="4"] {
  margin-right: .278em;
}

mjx-container [rspace="5"] {
  margin-right: .333em;
}

mjx-container [size="s"] {
  font-size: 70.7%;
}

mjx-container [size="ss"] {
  font-size: 50%;
}

mjx-container [size="Tn"] {
  font-size: 60%;
}

mjx-container [size="sm"] {
  font-size: 85%;
}

mjx-container [size="lg"] {
  font-size: 120%;
}

mjx-container [size="Lg"] {
  font-size: 144%;
}

mjx-container [size="LG"] {
  font-size: 173%;
}

mjx-container [size="hg"] {
  font-size: 207%;
}

mjx-container [size="HG"] {
  font-size: 249%;
}

mjx-container [width="full"] {
  width: 100%;
}

mjx-box {
  display: inline-block;
}

mjx-block {
  display: block;
}

mjx-itable {
  display: inline-table;
}

mjx-row {
  display: table-row;
}

mjx-row > mjx-cell, mjx-row > mjx-base, mjx-row > mjx-under, mjx-row > mjx-over, mjx-row > mjx-den {
  display: table-cell;
}

mjx-container [inline-breaks] {
  display: inline;
}

mjx-container .mjx-selected {
  outline: 2px solid black;
}

@media (prefers-color-scheme: dark) {
  mjx-container .mjx-selected {
    outline: 2px solid #C8C8C8;
  }
}

mjx-mtext {
  display: inline-block;
  text-align: left;
}

mjx-mstyle {
  display: inline-block;
}

mjx-merror {
  display: inline-block;
  color: red;
  background-color: yellow;
}

mjx-mphantom {
  visibility: hidden;
}

mjx-container[has-speech="true"] {
  position: relative;
  cursor: default;
}

mjx-speech {
  position: absolute;
  z-index: -1;
  left: 0;
  top: 0;
  bottom: 0;
  right: 0;
}

mjx-speech:focus {
  outline: none;
}

mjx-container a[data-mjx-href] {
  color: LinkText;
  cursor: pointer;
}

mjx-container a[data-mjx-href].mjx-visited {
  color: VisitedText;
}

mjx-container > mjx-help {
  display: none;
  position: absolute;
  top: -.3em;
  right: -.5em;
  width: .6em;
  height: .6em;
  cursor: pointer;
}

mjx-container[display="true"] > mjx-help {
  position: sticky;
  inset: -100% 0 100% 0;
  margin: -.3em -.5em 0 -.1em;
  right: 0;
  top: initial;
}

mjx-help > svg {
  stroke: black;
  width: 100%;
  height: 100%;
}

mjx-help > svg > circle {
  stroke-width: 1.5px;
  cx: 9px;
  cy: 9px;
  r: 9px;
  fill: white;
}

mjx-help > svg > circle:nth-child(2) {
  fill: var(--mjx-bg1-color);
  r: 7px;
}

mjx-help > svg > line {
  stroke-width: 2.5px;
  stroke-linecap: round;
}

mjx-help:hover > svg > circle:nth-child(2) {
  fill: white;
}

mjx-container.mjx-explorer-active > mjx-help {
  display: inline-flex;
  align-items: center;
}

@media (prefers-color-scheme: dark) /* explorer */ {
  mjx-help > svg {
    stroke: #E0E0E0;
  }
  mjx-help > svg > circle {
    fill: #404040;
  }
  mjx-help > svg > circle:nth-child(2) {
    fill: rgba(132, 132, 255, .3);
  }
  mjx-help:hover > svg > circle:nth-child(2) {
    stroke: #AAAAAA;
      fill: #404040;
  }
}

mjx-math {
  display: inline-block;
  text-align: left;
  line-height: 0;
  text-indent: 0;
  font-style: normal;
  font-weight: normal;
  font-size: 100%;
  font-size-adjust: none;
  letter-spacing: normal;
  word-wrap: normal;
  word-spacing: normal;
  direction: ltr;
  padding: 1px 0;
}

mjx-container[jax="CHTML"][display="true"] mjx-math {
  padding: 0;
}

mjx-math[breakable] {
  display: inline;
}

mjx-container[jax="CHTML"] mjx-break {
  white-space: normal;
  line-height: 0;
  clip-path: rect(0 0 0 0);
  font-family: MJX-BRK !important;
}

mjx-break[size="0"] {
  letter-spacing: -0.999em;
}

mjx-break[size="1"] {
  letter-spacing: -0.889em;
}

mjx-break[size="2"] {
  letter-spacing: -0.833em;
}

mjx-break[size="3"] {
  letter-spacing: -0.778em;
}

mjx-break[size="4"] {
  letter-spacing: -0.722em;
}

mjx-break[size="5"] {
  letter-spacing: -0.667em;
}

mjx-menclose {
  display: inline-block;
  text-align: left;
  position: relative;
}

mjx-menclose > mjx-dstrike {
  display: inline-block;
  left: 0;
  top: 0;
  position: absolute;
  border-top: 0.067em solid;
  transform-origin: top left;
}

mjx-menclose > mjx-ustrike {
  display: inline-block;
  left: 0;
  bottom: 0;
  position: absolute;
  border-top: 0.067em solid;
  transform-origin: bottom left;
}

mjx-menclose > mjx-hstrike {
  border-top: 0.067em solid;
  position: absolute;
  left: 0;
  right: 0;
  bottom: 50%;
  transform: translateY(0.034em);
}

mjx-menclose > mjx-vstrike {
  border-left: 0.067em solid;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 50%;
  transform: translateX(0.034em);
}

mjx-menclose > mjx-rbox {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  left: 0;
  border: 0.067em solid;
  border-radius: 0.267em;
}

mjx-menclose > mjx-cbox {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  left: 0;
  border: 0.067em solid;
  border-radius: 50%;
}

mjx-menclose > mjx-arrow {
  position: absolute;
  left: 0;
  bottom: 50%;
  height: 0;
  width: 0;
}

mjx-menclose > mjx-arrow > mjx-aline {
  display: block;
  position: absolute;
  box-sizing: border-box;
  transform-origin: bottom;
  left: 0;
  top: -0.034em;
  right: 0.201em;
  height: 0;
  border-top: 0.067em solid;
  border-left: 0;
  border-right: 0;
}

mjx-menclose > mjx-arrow[double] > mjx-aline {
  display: block;
  position: absolute;
  box-sizing: border-box;
  transform-origin: bottom;
  left: 0.201em;
  height: 0;
  border-left: 0.268em solid;
  border-right: 0;
}

mjx-menclose > mjx-arrow > mjx-rthead {
  display: block;
  position: absolute;
  box-sizing: border-box;
  transform-origin: bottom;
  transform: skewX(0.464rad);
  right: 0;
  bottom: -1px;
  border-left: 0.268em solid;
  border-right: 0;
  border-bottom: 1px solid transparent;
  border-top: 0.134em solid transparent;
}

mjx-menclose > mjx-arrow > mjx-rbhead {
  display: block;
  position: absolute;
  box-sizing: border-box;
  transform: skewX(-0.464rad);
  transform-origin: top;
  right: 0;
  top: -1px;
  border-left: 0.268em solid;
  border-right: 0;
  border-top: 1px solid transparent;
  border-bottom: 0.134em solid transparent;
}

mjx-menclose > mjx-arrow > mjx-lthead {
  display: block;
  position: absolute;
  box-sizing: border-box;
  transform: skewX(-0.464rad);
  transform-origin: bottom;
  left: 0;
  bottom: -1px;
  border-left: 0;
  border-right: 0.268em solid;
  border-bottom: 1px solid transparent;
  border-top: 0.134em solid transparent;
}

mjx-menclose > mjx-arrow > mjx-lbhead {
  display: block;
  position: absolute;
  box-sizing: border-box;
  transform: skewX(0.464rad);
  transform-origin: top;
  left: 0;
  top: -1px;
  border-left: 0;
  border-right: 0.268em solid;
  border-top: 1px solid transparent;
  border-bottom: 0.134em solid transparent;
}

mjx-menclose > mjx-dbox-top {
  position: absolute;
  top: 0;
  bottom: 50%;
  left: 0;
  width: 0.3em;
  border-width: 0.067em;
  border-style: solid solid none none;
  border-radius: 0 100% 0 0;
  box-sizing: border-box;
}

mjx-menclose > mjx-dbox-bot {
  position: absolute;
  top: 50%;
  bottom: 0;
  left: 0;
  width: 0.3em;
  border-width: 0.067em;
  border-style: none solid solid none;
  border-radius: 0 0 100% 0;
  box-sizing: border-box;
}

mjx-TeXAtom {
  display: inline-block;
  text-align: left;
}

mjx-mrow {
  display: inline-block;
  text-align: left;
}

mjx-linestack, mjx-mrow[break-top] {
  display: inline-table;
  width: 100%;
}

mjx-linestack[break-align="bottom"], mjx-mrow[break-top][break-align="bottom"] {
  display: inline-block;
}

mjx-linestack[break-align="middle"], mjx-mrow[break-top][break-align="middle"] {
  vertical-align: middle;
}

mjx-linestack[break-align="center"], mjx-mrow[break-top][break-align="center"] {
  vertical-align: middle;
}

mjx-linestack[breakable] {
  display: inline;
}

mjx-linestack[breakable] > mjx-linebox {
  display: inline;
}

mjx-linestack[breakable] > mjx-linebox::before {
  white-space: pre;
  content: "\A";
}

mjx-linestack[breakable] > mjx-linebox::after {
  white-space: normal;
  content: " ";
  letter-spacing: -.999em;
  font-family: MJX-BRK;
}

mjx-linestack[breakable] > mjx-linebox:first-of-type::before {
  display: none;
}

mjx-linestack[breakable] > mjx-linebox:last-of-type::after {
  display: none;
}

mjx-linebox {
  display: block;
}

mjx-linebox[align="left"] {
  text-align: left;
}

mjx-linebox[align="center"] {
  text-align: center;
}

mjx-linebox[align="right"] {
  text-align: right;
}

mjx-linestrut {
  display: inline-block;
  height: 1em;
  vertical-align: -.25em;
}

mjx-munder {
  display: inline-block;
  text-align: left;
}

mjx-over {
  text-align: left;
}

mjx-munder:not([limits="false"]) {
  display: inline-table;
}

mjx-munder > mjx-row {
  text-align: left;
}

mjx-under {
  padding-bottom: .1em;
}

mjx-msubsup {
  display: inline-block;
  text-align: left;
}

mjx-script {
  display: inline-block;
  padding-right: .05em;
  padding-left: .033em;
}

mjx-script > mjx-spacer {
  display: block;
}

mjx-mo {
  display: inline-block;
  text-align: left;
}

mjx-stretchy-h > mjx-beg, mjx-stretchy-h > mjx-ext, mjx-stretchy-h > mjx-end, mjx-stretchy-h > mjx-mid {
  display: inline-block;
  width: 0;
  text-align: right;
}

mjx-stretchy-h > mjx-ext {
  clip-path: padding-box polygon(0 -1em, 100% -1em, 100% calc(100% + 1em), 0 calc(100% + 1em));
  width: 100%;
  border: 0px solid transparent;
  box-sizing: border-box;
  text-align: left;
}

mjx-stretchy-v > mjx-beg, mjx-stretchy-v > mjx-ext, mjx-stretchy-v > mjx-end, mjx-stretchy-v > mjx-mid {
  display: block;
  height: 0;
  margin: 0 auto;
}

mjx-stretchy-v > mjx-ext > mjx-spacer {
  display: block;
}

mjx-stretchy-v > mjx-ext {
  clip-path: padding-box polygon(-1em 0, calc(100% + 1em) 0, calc(100% + 1em) 100%, -1em 100%);
  height: 100%;
  border: 0.1px solid transparent;
  box-sizing: border-box;
  white-space: pre;
}

mjx-mark {
  display: inline-block;
  height: 0;
}

mjx-c {
  display: inline-block;
  width: 0;
  text-align: right;
}

mjx-utext {
  display: inline-block;
  padding: .75em 0 .2em 0;
}

mjx-mi {
  display: inline-block;
  text-align: left;
}

mjx-mn {
  display: inline-block;
  text-align: left;
}

mjx-msub {
  display: inline-block;
  text-align: left;
}

mjx-mpadded {
  display: inline-block;
  text-align: left;
}

mjx-rbox {
  display: inline-block;
  position: relative;
}

mjx-mspace {
  display: inline-block;
  text-align: left;
}

mjx-mfrac {
  display: inline-block;
  text-align: left;
}

mjx-frac {
  display: inline-block;
  vertical-align: 0.17em;
  padding: 0 .22em;
}

mjx-frac[type="d"] {
  vertical-align: .04em;
}

mjx-frac[delims] {
  padding: 0 .1em;
}

mjx-frac[atop] {
  padding: 0 .12em;
}

mjx-frac[atop][delims] {
  padding: 0;
}

mjx-dtable {
  display: inline-table;
  width: 100%;
}

mjx-dtable > mjx-line, mjx-dtable > mjx-row {
  font-size: 2000%;
}

mjx-dbox {
  display: block;
  font-size: 5%;
}

mjx-num {
  display: block;
  text-align: center;
}

mjx-den {
  display: block;
  text-align: center;
}

mjx-mfrac[bevelled] > mjx-num {
  display: inline-block;
}

mjx-mfrac[bevelled] > mjx-den {
  display: inline-block;
}

mjx-den[align="right"], mjx-num[align="right"] {
  text-align: right;
}

mjx-den[align="left"], mjx-num[align="left"] {
  text-align: left;
}

mjx-nstrut {
  display: inline-block;
  height: .054em;
  width: 0;
  vertical-align: -.054em;
}

mjx-nstrut[type="d"] {
  height: .217em;
  vertical-align: -.217em;
}

mjx-dstrut {
  display: inline-block;
  height: .505em;
  width: 0;
}

mjx-dstrut[type="d"] {
  height: .726em;
}

mjx-line {
  display: block;
  box-sizing: border-box;
  min-height: 1px;
  height: .06em;
  border-top: .075em solid;
  margin: .06em -.1em;
  overflow: hidden;
}

mjx-line[type="d"] {
  margin: .18em -.1em;
}

mjx-msqrt {
  display: inline-block;
  text-align: left;
}

mjx-root {
  display: inline-block;
  white-space: nowrap;
}

mjx-surd {
  display: inline-block;
  vertical-align: top;
}

mjx-sqrt {
  display: inline-block;
  padding-top: .075em;
}

mjx-sqrt > mjx-box {
  border-top: .075em solid;
  padding-left: .03em;
  margin-left: -.03em;
}

mjx-sqrt.mjx-tall > mjx-box {
  padding-left: .3em;
  margin-left: -.3em;
}

mjx-msup {
  display: inline-block;
  text-align: left;
}

mjx-mtable {
  display: inline-block;
  text-align: center;
  vertical-align: .25em;
  position: relative;
